CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_chat ON messages(chat_id, id);
CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT NOT NULL, author TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reminders (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT NOT NULL, text TEXT NOT NULL, due_at INTEGER NOT NULL, repeat TEXT NOT NULL DEFAULT 'none', author TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reminders_due ON reminders(due_at);
CREATE TABLE IF NOT EXISTS kb_docs (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, chunks INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT 'doc');
CREATE VIRTUAL TABLE IF NOT EXISTS kb_fts USING fts5(content, doc_id UNINDEXED, doc_name UNINDEXED, tokenize = "unicode61 remove_diacritics 2");
CREATE TABLE IF NOT EXISTS sessions (chat_id TEXT PRIMARY KEY, doc_id INTEGER NOT NULL, kind TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS event_log (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT, body TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS last_media (chat_id TEXT PRIMARY KEY, url TEXT, media_type TEXT, name TEXT, doc_id INTEGER, at INTEGER NOT NULL);
